import React from 'react';

const Impact = () => {
    return (
        <div>
            <h1>Impact of SoochnaPreneur</h1>
            <p>
                The SoochnaPreneur initiative has made significant strides in empowering communities through information and technology. 
                Our impact can be seen in various areas, including increased access to resources, enhanced entrepreneurial skills, 
                and improved livelihoods for many individuals.
            </p>
            <h2>Key Achievements</h2>
            <ul>
                <li>Over 1,000 individuals trained in digital literacy.</li>
                <li>Creation of 200+ small businesses through our support programs.</li>
                <li>Partnerships with local organizations to expand outreach.</li>
                <li>Successful campaigns raising awareness about digital tools.</li>
            </ul>
            <h2>Testimonials</h2>
            <blockquote>
                "SoochnaPreneur has changed my life. I now run my own business and can support my family." - A SoochnaPreneur Graduate
            </blockquote>
        </div>
    );
};

export default Impact;
